<a class="back-link" href="<?= $e($url('table',['id'=>$lead['import_id']])) ?>">← К таблице</a><div class="page-heading"><div><div class="eyebrow">КАРТОЧКА КОНТАКТА</div><h1><?= $e($lead['company']) ?: 'Контакт без названия' ?></h1><p class="muted"><?= $e($lead['address']) ?></p></div><?php if ($tel=Contacts\Normalizer::tel($phone)): ?><a class="button primary" href="<?= $e($tel) ?>">Позвонить <?= $e($phone) ?></a><?php endif ?></div>
<div class="note-grid"><section class="card"><h2>Новая запись</h2><form method="post" action="<?= $e($url('note_save',['id'=>$lead['id']])) ?>" class="stack" data-busy><?= self::csrf() ?><div class="form-row"><label>Системный № контакта<input readonly value="<?= $e($lead['id']) ?>"></label><label>Телефон<select name="phone"><?php foreach (array_filter(explode('; ',$lead['phones'])) as $p): ?><option <?= $p===$phone?'selected':'' ?>><?= $e($p) ?></option><?php endforeach ?><?php if (!$lead['phones']): ?><option value="">Не указан</option><?php endif ?></select></label></div><div class="form-row"><label>Дата<input type="date" name="contact_date" min="1000-01-01" max="9999-12-31"></label><label>Дата 2 <span class="optional">повторный контакт</span><input type="date" name="followup_date" min="1000-01-01" max="9999-12-31"></label></div><label>Комментарий<textarea name="comment" rows="5" maxlength="10000" placeholder="Результат разговора или заметка"></textarea></label><button class="button primary">Сохранить запись</button></form></section><section class="card"><h2>История контакта <span class="count-badge"><?= count($notes) ?></span></h2><?php if (!$notes): ?><div class="empty"><h3>Записей пока нет</h3><p>Сохранённые комментарии появятся здесь.</p></div><?php endif ?><?php foreach ($notes as $note): ?><article class="note"><div class="section-title"><strong>Запись №<?= $e($note['id']) ?></strong><time class="muted"><?= $e($note['created_at']) ?></time></div><p><?= nl2br($e($note['comment'])) ?: 'Без комментария' ?></p><small class="muted"><?= $e($note['phone']) ?> · Дата: <?= $e($note['contact_date'] ?: 'не указана') ?> · Дата 2: <?= $e($note['followup_date'] ?: 'не указана') ?></small></article><?php endforeach ?></section></div>
